#include <stdio.h>

#define M 101

int ht[M];

int lcg(int *st) {
    *st = ((*st) * 1103515245 + 12345) & 0x7fffffff;
    return *st;
}

int main(void) {
    int alpha_n[] = {25, 50, 75, 90};
    int t, n, i, state, inserted, key, h0, j, c, total;
    int nn = (int)(sizeof(alpha_n) / sizeof(alpha_n[0]));
    for (t = 0; t < nn; t++) {
        n = alpha_n[t];
        for (i = 0; i < M; i++) ht[i] = -1;
        state = 12345;
        inserted = 0;
        while (inserted < n) {
            key = lcg(&state) % 1000;
            h0 = key % M;
            j = h0;
            while (ht[j] != -1) { j = (j + 1) % M; }
            ht[j] = key;
            inserted++;
        }
        total = 0;
        for (i = 0; i < M; i++) {
            if (ht[i] == -1) continue;
            key = ht[i];
            h0 = key % M;
            j = h0; c = 1;
            while (ht[j] != -1 && ht[j] != key) { j = (j + 1) % M; c++; }
            total += c;
        }
        {
            double a = (double)n / (double)M;
            double asl = (double)total / (double)n;
            printf("alpha=%.3f (n=%d/M=%d)  成功查找平均探测 ASL=%.3f  (理论 1/(1-a)=%.3f)\n",
                   a, n, M, asl, 1.0 / (1.0 - a));
        }
    }
    return 0;
}
